#include "../RahiTuber/SpriteSheet.h"
#include <iostream>
#include <stdexcept>
#include <filesystem>
static void check(bool good,const char* why){if(!good)throw std::runtime_error(why);}
int main(){try{auto path=std::filesystem::temp_directory_path()/"pngmax-edge-render.png";sf::Image image;image.create(32,32,sf::Color::Transparent);for(int y=0;y<32;++y)for(int x=0;x<32;++x)if((x-16)*(x-16)+(y-16)*(y-16)<=144)image.setPixel(x,y,{100,150,220,255});image.setPixel(16,16,{240,40,90,255});image.saveToFile(path.string());TextureManager textures;SpriteSheet first,second,back;for(auto* sprite:{&first,&second,&back})sprite->LoadFromTexture(&textures,path.string(),1,1,1,1);sf::RenderTexture target;check(target.create(32,32),"Edge render target failed");sf::RenderStates state;state.blendMode=sf::BlendMode(sf::BlendMode::One,sf::BlendMode::OneMinusSrcAlpha);
 auto draw=[&](SpriteSheet& sprite,bool plush=false,bool attached=false){target.clear(sf::Color::Transparent);if(attached)back.DrawAttachment(&target,sprite,sf::Transform::Identity,state,[](sf::Vector2f p){return p;});else if(plush)sprite.DrawPlush(&target,back,.45f,0,state);else sprite.Draw(&target,state);target.display();return target.getTexture().copyToImage();};
 auto original=draw(first);first.edgeFeather=4;auto faded=draw(first);check(faded.getPixel(16,4).a<64&&faded.getPixel(16,16)==original.getPixel(16,16),"Silhouette feather changes mouth interior or uses a box fade");auto preview=first.EdgePreview()->copyToImage().getPixel(16,4);check(preview.a==faded.getPixel(16,4).a&&preview.b>180,"Editor preview darkens premultiplied edges");check(draw(second).getPixel(16,4)==original.getPixel(16,4)&&first.getTexture()->copyToImage().getPixel(16,4).a==255,"Per-slot edges mutate the shared PNG");check(draw(first,false,true).getPixel(16,4).a<64,"Attached image bypasses feathering");auto plushSoft=draw(first,true);first.edgeFeather=0;auto plushRaw=draw(first,true);check(plushSoft.getPixel(16,4).a<plushRaw.getPixel(16,4).a&&plushSoft.getPixel(16,16)==plushRaw.getPixel(16,16),"Plush texture does not retain edge blending or sharp interior");
 first.edgeFeather=4;first.edgeTrim=1;SpriteSheet copied(first);check(copied.edgeFeather==4&&copied.edgeTrim==1,"Copy loses edge settings");first.edgeFeather=first.edgeTrim=0;auto reset=draw(first);for(unsigned y=0;y<32;++y)for(unsigned x=0;x<32;++x)check(reset.getPixel(x,y)==original.getPixel(x,y),"Reset does not restore original rendered pixels");
 std::filesystem::remove(path);std::cout<<"PASS: per-slot silhouette feather, sharp interior, immutable shared source, attached/plush rendering, copy and pixel-exact reset\n";
 }catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
